records = []
pk = 25  # existing fixture already uses pk 1-24 for maize/gardenbean/cassava
for crop_name, stages in CROPS.items():
    for stage in STAGES:
        title, description = stages[stage]
        records.append({
            "model": "advisory.cropadvisory",
            "pk": pk,
            "fields": {
                "crop_name": crop_name,
                "stage": stage,
                "title": title,
                "description": description,
            },
        })
        pk += 1

existing = json.load(open("advisory/fixtures/advisory_seed.json"))
combined = existing + records

with open("advisory/fixtures/advisory_seed.json", "w") as f:
    json.dump(combined, f, indent=2)
    f.write("\n")

print(f"Added {len(records)} records for {len(CROPS)} crops. Fixture now has {len(combined)} total records.")
